bad:
for _, value := range values {
    value := value
    go use(value)
}

good:
for _, value := range values {
    go use(value)
}

bad:
//go:build linux
// +build linux

package example

func contains(values []int, wanted int) bool {
    for _, value := range values { if value == wanted { return true } }
    return false
}

good:
func contains(values []int, wanted int) bool {
    return slices.Contains(values, wanted)
}

bad:
if strings.HasPrefix(input, prefix) {
    use(strings.TrimPrefix(input, prefix))
}

good:
if remainder, found := strings.CutPrefix(input, prefix); found {
    use(remainder)
}

bad:
var text string
for _, part := range parts { text += part }
use(text)

good:
var text strings.Builder
for _, part := range parts { text.WriteString(part) }
use(text.String())

